import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import {
  createFlvParser,
  parseVideoTag,
  buildVideoTag,
  writeFlvHeader,
  writeTag,
  TAG_VIDEO,
  TAG_AUDIO,
  TAG_SCRIPT,
  AVC_NALU,
  AVC_SEQUENCE_HEADER,
} from '../lib/flv.js';

const ffmpegOk = spawnSync('ffmpeg', ['-version'], { stdio: 'ignore' }).status === 0;

/** Two-second H.264 + AAC FLV with B-frames, generated by the real ffmpeg. */
function makeFixture() {
  const dir = mkdtempSync(join(tmpdir(), 'flv-fixture-'));
  try {
    const out = join(dir, 'fixture.flv');
    const r = spawnSync('ffmpeg', [
      '-hide_banner', '-loglevel', 'error', '-y',
      '-f', 'lavfi', '-i', 'testsrc=size=160x120:rate=25',
      '-f', 'lavfi', '-i', 'sine',
      '-c:v', 'libx264', '-bf', '2', '-g', '25', '-c:a', 'aac',
      '-t', '2', '-f', 'flv', out,
    ], { encoding: 'utf8', timeout: 60000 });
    assert.equal(r.status, 0, r.stderr);
    return readFileSync(out);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

/** Deterministic PRNG (mulberry32) so a failing chunk pattern can be reproduced. */
function rng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function parseAll(buffer) {
  const parser = createFlvParser();
  return parser.push(buffer);
}

function parseInChunks(buffer, sizeFor) {
  const parser = createFlvParser();
  const items = [];
  let offset = 0;
  while (offset < buffer.length) {
    const size = sizeFor();
    items.push(...parser.push(buffer.subarray(offset, offset + size)));
    offset += size;
  }
  assert.equal(parser.pendingBytes(), 0, 'nothing left unparsed at end of input');
  return items;
}

/** Re-write parsed items; the header item gives the flags, tags are passed through. */
function rewrite(items) {
  const header = items[0];
  assert.equal(header.kind, 'header');
  const parts = [writeFlvHeader({ audio: header.audio, video: header.video, version: header.version, dataOffset: header.dataOffset })];
  for (const item of items.slice(1)) {
    parts.push(writeTag({ type: item.type, timestamp: item.timestamp, streamId: item.streamId, data: item.data }));
  }
  return Buffer.concat(parts);
}

const fixture = ffmpegOk ? makeFixture() : null;
const skipNoFfmpeg = ffmpegOk ? false : 'ffmpeg not on PATH';

test('ffmpeg FLV: fed in random-sized chunks, every tag re-writes byte-identical', { skip: skipNoFfmpeg }, () => {
  const random = rng(42);
  const sizeFor = () => 1 + Math.floor(random() * (random() < 0.1 ? 4000 : 200));
  const items = parseInChunks(fixture, sizeFor);

  assert.equal(items[0].kind, 'header');
  assert.equal(items[0].video, true);
  assert.equal(items[0].audio, true);
  // Same items as parsing the whole file in one push.
  assert.deepEqual(items, parseAll(fixture));
  assert.ok(Buffer.compare(rewrite(items), fixture) === 0, 're-written FLV is byte-identical');
});

test('ffmpeg FLV: carries the AVC structure the captioner needs', { skip: skipNoFfmpeg }, () => {
  const tags = parseAll(fixture).filter((i) => i.kind === 'tag');
  assert.ok(tags.some((t) => t.type === TAG_SCRIPT), 'script (metadata) tag present');
  const video = tags.filter((t) => t.type === TAG_VIDEO).map((t) => parseVideoTag(t.data));
  assert.ok(tags.some((t) => t.type === TAG_AUDIO), 'audio tags present');
  assert.equal(video.filter((v) => v.avcPacketType === AVC_SEQUENCE_HEADER).length, 1, 'one sequence header');
  assert.ok(video.find((v) => v.avcPacketType === AVC_SEQUENCE_HEADER).config.length > 0, 'config record kept');
  assert.ok(video.some((v) => v.avcPacketType === AVC_NALU && v.nalus.length > 0), 'NAL unit packets present');
  // Each NALU packet of this encoder holds one frame, so the lengths must reach the end.
  for (const v of video.filter((x) => x.avcPacketType === AVC_NALU)) {
    assert.ok(v.nalus.every((n) => n.length > 0), 'no empty NAL units');
  }
  assert.ok(video.some((v) => v.compositionTime !== 0), 'B-frames give a non-zero composition time');
});

test('ffmpeg FLV: a split inside every header field still parses to the same items', { skip: skipNoFfmpeg }, () => {
  // One byte at a time covers splits inside the file header, the 4-byte
  // PreviousTagSize fields and the 11-byte tag headers.
  const oneShot = parseAll(fixture);
  const items = parseInChunks(fixture, () => 1);
  assert.deepEqual(items, oneShot);
});

test('extended timestamp: the high byte is read and written back', () => {
  const ts = 0x01000000 + 1234; // 2^24 + 1234 ms: needs TimestampExtended = 1
  const data = Buffer.from([0x17, 0x01, 0x00, 0x00, 0x00, 0xaa]);
  const tagBytes = writeTag({ type: TAG_VIDEO, timestamp: ts, data });
  assert.equal(tagBytes[7], 1, 'extended byte written');
  assert.equal(tagBytes.readUIntBE(4, 3), 1234, 'low 24 bits written');

  const header = writeFlvHeader({ video: true });
  const [item] = parseAll(Buffer.concat([header, tagBytes])).slice(1);
  assert.equal(item.timestamp, ts);
  assert.equal(item.type, TAG_VIDEO);
  assert.equal(item.streamId, 0);
  assert.deepEqual(item.data, data);
  assert.ok(Buffer.compare(rewrite([parseAll(Buffer.concat([header, tagBytes]))[0], item]), Buffer.concat([header, tagBytes])) === 0);
});

test('extended timestamp: a high bit set in the extended byte stays unsigned', () => {
  const ts = 0xfffffff0; // extended byte 0xff
  const tagBytes = writeTag({ type: TAG_AUDIO, timestamp: ts, data: Buffer.alloc(0) });
  const items = parseAll(Buffer.concat([writeFlvHeader({ audio: true }), tagBytes]));
  assert.equal(items[1].timestamp, ts);
});

test('negative composition time: signed 24-bit both ways', () => {
  const tag = buildVideoTag({ frameType: 2, avcPacketType: AVC_NALU, compositionTime: -40, nalus: [Buffer.from([0x41, 0x9a])] });
  assert.deepEqual([...tag.subarray(2, 5)], [0xff, 0xff, 0xd8]);
  assert.equal(parseVideoTag(tag).compositionTime, -40);

  const min = buildVideoTag({ frameType: 1, avcPacketType: AVC_NALU, compositionTime: -8388608, nalus: [] });
  assert.equal(parseVideoTag(min).compositionTime, -8388608);
  const max = buildVideoTag({ frameType: 1, avcPacketType: AVC_NALU, compositionTime: 8388607, nalus: [] });
  assert.equal(parseVideoTag(max).compositionTime, 8388607);
  assert.throws(() => buildVideoTag({ frameType: 1, avcPacketType: AVC_NALU, compositionTime: 8388608 }), RangeError);
});

test('NALU split and join round trip (4-byte length prefixes)', () => {
  const nalus = [
    Buffer.from([0x67, 0x42, 0x00, 0x1f]), // SPS-like
    Buffer.from([0x68, 0xce, 0x3c, 0x80]), // PPS-like
    Buffer.alloc(300, 0x11), // larger than one length byte
    Buffer.from([0x65]), // one byte
  ];
  const data = buildVideoTag({ frameType: 1, avcPacketType: AVC_NALU, compositionTime: 80, nalus });
  assert.equal(data.length, 5 + nalus.reduce((n, x) => n + 4 + x.length, 0));
  assert.equal(data.readUInt32BE(5), 4, 'first prefix is 4');

  const parsed = parseVideoTag(data);
  assert.equal(parsed.frameType, 1);
  assert.equal(parsed.codecId, 7);
  assert.equal(parsed.avcPacketType, AVC_NALU);
  assert.equal(parsed.compositionTime, 80);
  assert.equal(parsed.nalus.length, nalus.length);
  parsed.nalus.forEach((n, i) => assert.deepEqual(n, nalus[i]));
  assert.deepEqual(buildVideoTag(parsed), data);
});

test('sequence header keeps the raw config record; end of sequence has no payload', () => {
  const config = Buffer.from([0x01, 0x42, 0xc0, 0x1f, 0xff, 0xe1, 0x00, 0x02, 0x67, 0x42]);
  const seq = buildVideoTag({ frameType: 1, avcPacketType: AVC_SEQUENCE_HEADER, compositionTime: 0, config });
  const parsed = parseVideoTag(seq);
  assert.deepEqual(parsed.config, config);
  assert.deepEqual(parsed.nalus, []);
  assert.deepEqual(buildVideoTag(parsed), seq);

  const end = buildVideoTag({ frameType: 5, avcPacketType: 2 });
  assert.equal(end.length, 5);
  assert.equal(parseVideoTag(end).avcPacketType, 2);
});

test('non-AVC video tags are returned as body and rebuilt unchanged', () => {
  const data = Buffer.from([0x12, 0xde, 0xad]); // frame 1, codec 2 (Sorenson)
  const parsed = parseVideoTag(data);
  assert.equal(parsed.codecId, 2);
  assert.deepEqual(parsed.body, Buffer.from([0xde, 0xad]));
  assert.deepEqual(buildVideoTag(parsed), data);
});

test('a truncated NAL unit length is rejected', () => {
  const bad = Buffer.from([0x17, 0x01, 0, 0, 0, 0, 0, 0, 9, 0x65]); // claims 9 bytes, has 1
  assert.throws(() => parseVideoTag(bad), /NAL unit runs past/);
});

test('split inside the 11-byte tag header and before the trailing size', () => {
  const header = writeFlvHeader({ video: true });
  const tagA = writeTag({ type: TAG_VIDEO, timestamp: 40, data: Buffer.from([0x17, 0x01, 0, 0, 0, 1, 2, 3]) });
  const tagB = writeTag({ type: TAG_AUDIO, timestamp: 41, data: Buffer.from([0xaf, 0x01, 9]) });
  const stream = Buffer.concat([header, tagA, tagB]);

  const parser = createFlvParser();
  const got = [];
  // Cut at every position of the first tag header (11 bytes) and its trailing size (4 bytes).
  const first = header.length;
  got.push(...parser.push(stream.subarray(0, first + 5))); // header + 5 bytes of tag header
  assert.equal(got.length, 1, 'header item only');
  got.push(...parser.push(stream.subarray(first + 5, first + tagA.length - 2))); // up to the trailing size
  assert.equal(got.length, 1, 'tag not complete until its PreviousTagSize is in');
  got.push(...parser.push(stream.subarray(first + tagA.length - 2, first + tagA.length))); // the size, split
  assert.equal(got.length, 2);
  assert.equal(got[1].timestamp, 40);
  got.push(...parser.push(stream.subarray(first + tagA.length, first + tagA.length + 1)));
  assert.equal(got.length, 2, 'half of the next tag header is not an item yet');
  assert.equal(parser.pendingBytes(), 1);
  got.push(...parser.push(stream.subarray(first + tagA.length + 1)));
  assert.equal(got.length, 3);
  assert.equal(got[2].type, TAG_AUDIO);
  assert.deepEqual(got[2].data, Buffer.from([0xaf, 0x01, 9]));
  assert.equal(parser.pendingBytes(), 0);
});

test('parser rejects a bad signature and a wrong PreviousTagSize', () => {
  assert.throws(() => parseAll(Buffer.from('MP4 not a flv file at all, really', 'latin1')), /bad signature/);

  const header = writeFlvHeader({ video: true });
  const tag = writeTag({ type: TAG_VIDEO, timestamp: 0, data: Buffer.from([0x17, 0x00]) });
  const broken = Buffer.from(tag);
  broken.writeUInt32BE(999, broken.length - 4);
  assert.throws(() => parseAll(Buffer.concat([header, broken])), /PreviousTagSize 999/);
});

test('writeTag and writeFlvHeader validate their input', () => {
  assert.throws(() => writeTag({ type: 256, data: Buffer.alloc(0) }), RangeError);
  assert.throws(() => writeTag({ type: 9, timestamp: -1, data: Buffer.alloc(0) }), RangeError);
  assert.throws(() => writeTag({ type: 9, timestamp: 2 ** 32, data: Buffer.alloc(0) }), RangeError);
  assert.throws(() => writeFlvHeader({ dataOffset: 8 }), RangeError);
  const h = writeFlvHeader({ audio: true, video: true });
  assert.equal(h.length, 13);
  assert.equal(h[4], 0x05);
  assert.equal(h.readUInt32BE(9), 0, 'PreviousTagSize0 is zero');
});
